// M67.27 full Apple path intentionally uses the 64 MiB M29 generator table.
// Keep a passive fetch audit so the result can report exactly which table URLs
// were requested, but do not block them.
const m6717NativeFetch = window.fetch.bind(window);
const m6717BlockedTableFetches = [];
const m6724TableFetches = [];
window.fetch = function m6724TrackedFetch(input, init) {
    const url = typeof input === "string"
        ? input
        : (input?.url ?? String(input));
    if (/generator-table/i.test(url)) {
        m6724TableFetches.push(url);
    }
    if (/generator-table-m29-16\.bin/i.test(url)) {
        throw new Error(`M67.38 blocked production 64 MiB table network fetch: ${url}`);
    }
    return m6717NativeFetch(input, init);
};
