// ============================================================================
// Focused UI — hide legacy milestone controls/results by default.
// This changes presentation only; legacy code remains available.
// ============================================================================

function photonFocusUi({
    mode,
}) {
    const allowedButtonIds =
        mode ===
            "test"
            ? new Set([
                "useM53ProvidedPayout",
                "preparePersistentTableCache",
                "clearPersistentTableCache",
                "runM50Live",
                "stopM50Live",
                "runM673Preflight",
                "runM673AdaptiveDiagnostic",
                "runOneGpuCpuSolution",
                "runM53RejectedReplay",
                "copyM673DiagnosticReport",
                "runM53HardwareDiagnostics",
                "runM64AdaptiveBatch",
            ])
            : new Set([
                "runM50Live",
                "stopM50Live",
                "m502ClearLifetime",
            ]);

    for (
        const button of
        document.querySelectorAll(
            "button[id]"
        )
    ) {
        if (
            !allowedButtonIds.has(
                button.id
            )
        ) {
            button.classList.add(
                "focus-hidden"
            );

            button.dataset.focusLegacy =
                "1";
        }
    }

    // Hide historical Milestone sections. The dedicated current GPU-debug card
    // has no Milestone heading and therefore remains visible.
    for (
        const heading of
        document.querySelectorAll(
            "h2"
        )
    ) {
        if (
            !heading.textContent
                .trim()
                .startsWith(
                    "Milestone "
                )
        ) {
            continue;
        }

        const section =
            heading.closest(
                "section"
            );

        if (
            section &&
            !section.classList.contains(
                "card"
            )
        ) {
            section.classList.add(
                "focus-hidden"
            );

            section.dataset.focusLegacy =
                "1";

            continue;
        }

        let node =
            heading;

        while (
            node
        ) {
            const next =
                node.nextElementSibling;

            node.classList.add(
                "focus-hidden"
            );

            node.dataset.focusLegacy =
                "1";

            if (
                !next ||
                next.tagName ===
                    "SECTION" ||
                next.tagName ===
                    "H2"
            ) {
                break;
            }

            node =
                next;
        }
    }

    const liveResult =
        document.querySelector(
            "#m50LiveResult"
        );

    const liveSection =
        liveResult?.closest(
            "section"
        );

    const dashboard =
        document.querySelector(
            "#m22Dashboard"
        );

    const dashboardCard =
        dashboard?.closest(
            "section.card"
        );

    if (
        liveSection &&
        dashboardCard
    ) {
        liveSection.classList.remove(
            "focus-hidden"
        );

        liveSection.classList.add(
            "card",
            "current-test-card"
        );

        liveSection.dataset.focusLegacy =
            "0";

        dashboardCard.insertAdjacentElement(
            "afterend",
            liveSection
        );

        const heading =
            liveSection.querySelector(
                "h2"
            );

        if (
            heading
        ) {
            heading.textContent =
                mode === "test"
                    ? "GPU validation result"
                    : "Live mining activity";
        }
    }

    const gpuDebug =
        document.querySelector(
            "#gpuDebugSection"
        );

    if (gpuDebug) {
        if (mode === "test") {
            gpuDebug.classList.remove("focus-hidden");
            gpuDebug.dataset.focusLegacy = "0";

            for (const id of [
                "runM673Preflight",
                "runM673AdaptiveDiagnostic",
                "runOneGpuCpuSolution",
                "runM53RejectedReplay",
                "copyM673DiagnosticReport",
                "runM53HardwareDiagnostics",
                "runM64AdaptiveBatch",
            ]) {
                const control = document.getElementById(id);
                control?.classList.remove("focus-hidden");
                if (control) control.dataset.focusLegacy = "0";
            }
        } else {
            gpuDebug.classList.add("focus-hidden");
            gpuDebug.dataset.focusLegacy = "1";
        }
    }

    if (mode !== "test") {
        for (const id of ["secureContext", "webGpuApi", "jsVersion", "adapterName"]) {
            const value = document.getElementById(id);
            if (!value) continue;
            value.classList.add("focus-hidden");
            const label = value.previousElementSibling;
            if (label) label.classList.add("focus-hidden");
        }
    }

    document.querySelector(
        "#legacyUiDisclosure"
    )?.remove();
}


photonFocusUi({ mode: "live" });




let m673LastDeviceLoss =
    null;


function m673EnvironmentLines() {
    const features =
        adapter
            ? Array.from(
                adapter.features
            ).sort()
            : [];

    const wgslFeatures =
        navigator.gpu
            ?.wgslLanguageFeatures
            ? Array.from(
                navigator.gpu
                    .wgslLanguageFeatures
            ).sort()
            : [];

    return [
        `Test version: M67.38-MainContinuousWins-v1`,
        `Timestamp: ${new Date().toISOString()}`,
        `Secure context: ${window.isSecureContext ? "YES" : "NO"}`,
        `WebGPU API: ${"gpu" in navigator ? "available" : "unavailable"}`,
        `Adapter: ${adapter ? m53AdapterInfoText() : "not initialized"}`,
        `Display adapter: ${adapter ? describeAdapter(adapter) : "not initialized"}`,
        `User agent: ${navigator.userAgent}`,
        `Adapter features: ${features.length > 0 ? features.join(", ") : "(none / unavailable)"}`,
        `WGSL language features: ${wgslFeatures.length > 0 ? wgslFeatures.join(", ") : "(none / unavailable)"}`,
        ...m53CriticalLimits().map(
            item =>
                `Limit: ${item}`
        ),
    ];
}


function m673RefreshAdapterDetails() {
    if (
        !ui.m673AdapterDetails
    ) {
        return;
    }

    if (
        !adapter
    ) {
        ui.m673AdapterDetails.textContent =
            "Enable WebGPU to populate.";

        return;
    }

    ui.m673AdapterDetails.textContent =
        [
            m53AdapterInfoText(),
            ...m53CriticalLimits(),
        ].join(
            " | "
        );
}


function m673RefreshAdaptiveFields(
    adaptive
) {
    if (
        !adaptive
    ) {
        return;
    }

    if (
        ui.m673AdaptiveBatch
    ) {
        ui.m673AdaptiveBatch.textContent =
            `${adaptive.batchSize.toLocaleString()} candidates`;
    }

    if (
        ui.m673AdaptiveValidation
    ) {
        ui.m673AdaptiveValidation.textContent =
            Number.isFinite(
                adaptive.averageValidationMs
            )
                ? `${adaptive.averageValidationMs.toFixed(1)} ms average`
                : "—";
    }

    if (
        ui.m673TableUpload
    ) {
        ui.m673TableUpload.textContent =
            adaptive.tableUploadMode ??
            "—";
    }

    if (
        ui.m673AdaptiveLadder
    ) {
        ui.m673AdaptiveLadder.textContent =
            Array.isArray(
                adaptive.ladderTimings
            )
                ? m67FormatLadderTimings(
                    adaptive.ladderTimings
                )
                : "—";
    }
}


function m673SavedProgressRecord() {
    try {
        return JSON.parse(
            localStorage.getItem(
                M57_PROGRESS_KEY
            ) ||
            "null"
        );
    } catch {
        return null;
    }
}


function m673BuildDiagnosticReport() {
    const progress =
        m673SavedProgressRecord();

    const adaptive =
        m65Prepared &&
        m65Prepared.device ===
            device
            ? m65Prepared
            : null;

    const lines = [
        "PHOTON GPU DIAGNOSTIC REPORT",
        "",
        ...m673EnvironmentLines(),
        "",
        "Current page state:",
        `Status: ${ui.status?.textContent ?? "n/a"}`,
        `Mainnet broadcast armed: ${ui.armLiveBroadcast?.checked ? "YES" : "NO"}`,
        `GPU intensity: ${ui.gpuIntensity?.value ?? "n/a"}%`,
        "",
        "Adaptive policy:",
        `Direct ladder minimum: ${M67_MIN_LADDER_BATCH.toLocaleString()} candidates`,
        `Target maximum batch time: ${M67_TARGET_BATCH_MS} ms`,
        `Escalate only while batch time <= ${M67_ESCALATE_BATCH_MS} ms`,
        "",
        "Current adaptive calibration:",
        adaptive
            ? `Selected batch: ${adaptive.batchSize.toLocaleString()} candidates`
            : "Selected batch: not calibrated in this device session",
        adaptive &&
        Number.isFinite(
            adaptive.averageValidationMs
        )
            ? `Validation: ${adaptive.averageValidationMs.toFixed(2)} ms average`
            : "Validation: n/a",
        adaptive
            ? `Table upload: ${adaptive.tableUploadMode ?? "n/a"}`
            : "Table upload: n/a",
        adaptive &&
        Array.isArray(
            adaptive.ladderTimings
        )
            ? `Direct ladder: ${m67FormatLadderTimings(adaptive.ladderTimings)}`
            : "Direct ladder: n/a",
        "",
        "Persistent 64 MiB generator-table cache (/test M67.36):",
        `OPFS supported: ${m6734PersistentTableState.opfsSupported ? "YES" : "NO"}`,
        `Persistent storage granted: ${m6734PersistentTableState.persistenceGranted === null ? "not checked" : (m6734PersistentTableState.persistenceGranted ? "YES" : "NO")}`,
        `Table source: ${m6734PersistentTableState.source}`,
        `Cached bytes: ${Number(m6734PersistentTableState.bytes || 0).toLocaleString()}`,
        `Cached SHA-256: ${m6734PersistentTableState.sha256 ?? "n/a"}`,
        `Network production-table bytes this session: ${Number(m6734PersistentTableState.networkBytesThisSession || 0).toLocaleString()}`,
        `OPFS table bytes this session: ${Number(m6734PersistentTableState.opfsBytesThisSession || 0).toLocaleString()}`,
        `Locally generated table bytes this session: ${Number(m6734PersistentTableState.generatedBytesThisSession || 0).toLocaleString()}`,
        m6734PersistentTableState.generationMs === null
            ? `Local generation time: n/a`
            : `Local generation time: ${(m6734PersistentTableState.generationMs / 1000).toFixed(2)} s`,
        m6734PersistentTableState.lastError
            ? `Cache error: ${m6734PersistentTableState.lastError}`
            : "Cache error: none",
        "",
        "Last WebGPU device loss this page load:",
        m673LastDeviceLoss
            ? `at=${m673LastDeviceLoss.at}, reason=${m673LastDeviceLoss.reason}, message=${m673LastDeviceLoss.message}`
            : "None observed.",
        "",
        "Last persisted staged-operation record:",
        progress
            ? JSON.stringify(
                progress,
                null,
                2
            )
            : "None.",
        "",
        "Latest diagnostic output:",
        ui.m53HardwareResult
            ?.textContent
            ?.trim() ||
            "(none)",
        "",
        "Privacy/safety:",
        "Mining private key included in this report: NO",
        "Mining private key transmitted by diagnostics: NO",
    ];

    return lines.join(
        "\n"
    );
}


function m673RefreshDiagnosticReport() {
    const report =
        m673BuildDiagnosticReport();

    if (
        ui.m673DiagnosticReport
    ) {
        ui.m673DiagnosticReport.textContent =
            report;
    }

    return report;
}


async function runM673StagedPreflightDiagnostic() {
    // M67.18 Apple compatibility page: legacy production preflight is intentionally
    // rerouted to the zero-table correctness test so stale HTML/buttons cannot
    // trigger any generator-table fetch.
    return await runOneGpuCpuSolutionCheck();
}


async function runM673AdaptiveDiagnostic() {
    // M67.18 Apple compatibility page: the normal adaptive-production diagnostic
    // requires the 64 MiB fixed-base table. Do not enter it here; run the direct
    // tableless A→B→C correctness/throughput path instead.
    return await runOneGpuCpuSolutionCheck();
}


async function m673CopyDiagnosticReport() {
    const report =
        m673RefreshDiagnosticReport();

    try {
        await navigator.clipboard.writeText(
            report
        );

        setStatus(
            "GPU diagnostic report copied to clipboard."
        );

    } catch (
        error
    ) {
        console.warn(
            "Clipboard copy failed.",
            error
        );

        setStatus(
            "Diagnostic report generated below; clipboard copy was unavailable."
        );
    }
}


