function resetWebGpuDeviceBoundCaches() {
    // Every object below is bound to the GPUDevice that created it. Keeping
    // any of them after a device loss can accidentally reuse dead D3D12/Dawn
    // resources after WebGPU is re-enabled.
    shaderModule = null;

    generatorTableBuffer = null;
    generatorTablePromise = null;
    singlePipelineProfilerPipeline = null;
    sustainedSearchPipeline = null;
    arbitraryKeySearchPipeline = null;

    m51Pipelines = new Map();
    m65Prepared = null;

    m47Pipelines = new Map();
    m46Pipelines = new Map();
    m45Pipelines = new Map();
    m43Pipelines = new Map();
    m42Pipelines = new Map();
    m40Pipelines = new Map();

    m39FixedDTableBuffer = null;
    m39FixedDTableKey = null;
    m39Pipelines = new Map();
    m38Pipelines = new Map();
    m37Pipelines = new Map();
    m36Pipelines = new Map();

    m35SignedTableBuffer = null;
    m35Pipelines = new Map();
    m34Pipelines = new Map();
    m33Pipelines = new Map();
    m32Pipelines = new Map();
    m31Pipelines = new Map();

    m30TxPrefixBuffer = null;
    m30Pipelines = new Map();
    m29TableBuffers = new Map();
    m29Pipelines = new Map();

    m28TableBuffer = null;
    m28TablePromise = null;
    m28Pipelines = new Map();

    m27TableBuffer = null;
    m27TablePromise = null;
    m27PrecomputedBuffer = null;
    m27Pipelines = new Map();

    m26GeneratorTableBuffer = null;
    m26GeneratorTablePromise = null;
    m26Pipelines = new Map();

    m25GeneratorTableBuffer = null;
    m25GeneratorTablePromise = null;
    m25Pipelines = new Map();

    m24GeneratorTableBuffer = null;
    m24GeneratorTablePromise = null;
    m24Pipelines = new Map();
    m23Pipelines = new Map();
}


function reconcileWebGpuOptInUi() {
    // Browsers may restore checkbox/form state across session restore or
    // back/forward navigation even though a GPUDevice cannot be restored with
    // that visual state. Never show "enabled" unless this JS context actually
    // owns a live device.
    if (
        !device &&
        ui.enableWebGpu.checked
    ) {
        ui.enableWebGpu.checked =
            false;

        setTestButtons(false);
    }
}


window.addEventListener(
    "pageshow",
    () => {
        // Run after browser form-state restoration has completed.
        setTimeout(
            reconcileWebGpuOptInUi,
            0
        );
    }
);

setTimeout(
    reconcileWebGpuOptInUi,
    0
);


function disableWebGpu() {
    adapter = null;
    device = null;
    resetWebGpuDeviceBoundCaches();

    ui.adapterName.textContent =
        "Not initialized";

    setTestButtons(false);

    setStatus(
        "WebGPU disabled by user."
    );

    m673RefreshAdapterDetails();
    m673RefreshDiagnosticReport();
}


function handleWebGpuDeviceLost(
    lostDevice,
    info
) {
    if (
        device !== lostDevice
    ) {
        return;
    }

    m673LastDeviceLoss = {
        at:
            new Date().toISOString(),
        reason:
            String(
                info?.reason ??
                "unknown"
            ),
        message:
            String(
                info?.message ??
                ""
            ),
    };

    const lossMessage =
        m673LastDeviceLoss.message ||
        m673LastDeviceLoss.reason;

    if (
        ui.m673DeviceLoss
    ) {
        ui.m673DeviceLoss.textContent =
            `reason=${m673LastDeviceLoss.reason}; ${m673LastDeviceLoss.message || "(no message)"}`;
    }

    console.error(
        "[PHOTON] Active WebGPU device lost:",
        info
    );

    m50StopRequested =
        true;

    m22StopRequested =
        true;

    if (
        ui.armLiveBroadcast
    ) {
        ui.armLiveBroadcast.checked =
            false;
    }

    ui.enableWebGpu.checked =
        false;

    adapter = null;
    device = null;
    resetWebGpuDeviceBoundCaches();

    ui.adapterName.textContent =
        "Device lost — re-enable required";

    setTestButtons(false);

    setStatus(
        `WebGPU device lost: ${lossMessage} — mining disarmed. Click Enable WebGPU once to acquire a fresh device.`
    );

    if (
        m50SavedControlStates !==
        null
    ) {
        if (
            ui.m22MiningState
        ) {
            ui.m22MiningState.textContent =
                "GPU DEVICE LOST — RUN DISARMED";
        }

        if (
            ui.m50LiveResult
        ) {
            setResult(
                ui.m50LiveResult,
                [
                    "STOPPED — WEBGPU DEVICE LOST DURING LIVE MINING.",
                    "",
                    `Reason: ${lossMessage}`,
                    "",
                    "The active GPUDevice is no longer usable.",
                    "All GPU-bound buffers and pipeline caches were invalidated.",
                    "Enable WebGPU was cleared.",
                    "BCH mainnet broadcast was DISARMED.",
                    "",
                    "To resume: enable WebGPU, verify the adapter, explicitly re-arm BCH broadcast, and start mining again.",
                ].join(
                    "\n"
                ),
                "fail"
            );
        }
    }

    m673RefreshAdapterDetails();
    m673RefreshDiagnosticReport();
}


ui.enableWebGpu.onclick =
    async () => {
        console.log(
            "[PHOTON] WebGPU checkbox click:",
            {
                checked:
                    ui.enableWebGpu.checked,
                hasLiveDevice:
                    Boolean(device),
            }
        );

        // The actual GPU state is authoritative. Chromium may restore the
        // checkbox's visual state after a browser/PC restart even though this
        // JavaScript context cannot possibly still own the old GPUDevice.
        // Therefore, if there is no live device, the FIRST user click always
        // means "enable WebGPU" regardless of the restored checked value.
        if (!device) {
            ui.enableWebGpu.checked =
                true;

            setTestButtons(false);

            setStatus(
                "WebGPU opt-in received…"
            );

            try {
                await initializeWebGpu();

                // Reflect the real state after acquisition succeeds.
                ui.enableWebGpu.checked =
                    true;

            } catch (error) {
                console.error(
                    "[PHOTON] WebGPU initialization failed:",
                    error
                );

                ui.enableWebGpu.checked =
                    false;

                adapter = null;
                device = null;
                resetWebGpuDeviceBoundCaches();

                ui.adapterName.textContent =
                    "Unavailable";

                const message =
                    error instanceof Error
                        ? error.message
                        : String(error);

                setStatus(
                    `WebGPU initialization failed: ${message}`
                );
            }

            return;
        }

        // If a live device exists, unchecking is a real user disable request.
        if (!ui.enableWebGpu.checked) {
            disableWebGpu();
            return;
        }

        // A click that leaves an already-live checkbox checked needs no work.
        setStatus(
            "WebGPU enabled. Ready to run tests."
        );
    };


function hexToBytes(hex) {
    if (
        typeof hex !== "string" ||
        hex.length % 2 !== 0 ||
        !/^[0-9a-fA-F]*$/.test(hex)
    ) {
        throw new Error("Invalid hexadecimal string.");
    }

    const bytes = new Uint8Array(hex.length / 2);

    for (
        let i = 0;
        i < bytes.length;
        i++
    ) {
        bytes[i] =
            Number.parseInt(
                hex.slice(
                    i * 2,
                    i * 2 + 2
                ),
                16
            );
    }

    return bytes;
}


function bytesToHex(bytes) {
    return Array.from(
        bytes,
        value =>
            value
                .toString(16)
                .padStart(2, "0")
    ).join("");
}


function uint32ToLittleEndianBytes(value) {
    const bytes = new Uint8Array(4);

    new DataView(
        bytes.buffer
    ).setUint32(
        0,
        value >>> 0,
        true
    );

    return bytes;
}


function buildPhotonMessage(
    nonce,
    targetHex
) {
    const nonceBytes =
        uint32ToLittleEndianBytes(nonce);

    const targetBytes =
        hexToBytes(targetHex);

    if (targetBytes.length !== 32) {
        throw new Error(
            "PHOTON target must be exactly 32 bytes."
        );
    }

    const message =
        new Uint8Array(36);

    message.set(
        nonceBytes,
        0
    );

    message.set(
        targetBytes,
        4
    );

    return message;
}


function bytesToBigEndianWords(
    bytes,
    wordCount
) {
    const words =
        new Uint32Array(wordCount);

    for (
        let byteIndex = 0;
        byteIndex < bytes.length;
        byteIndex++
    ) {
        const wordIndex =
            Math.floor(
                byteIndex / 4
            );

        const byteWithinWord =
            byteIndex % 4;

        const shift =
            24 -
            (
                byteWithinWord * 8
            );

        words[wordIndex] =
            (
                words[wordIndex] |
                (
                    bytes[byteIndex] << shift
                )
            ) >>> 0;
    }

    return words;
}


function digestWordsToHex(
    words,
    startWord = 0
) {
    const bytes =
        new Uint8Array(32);

    for (
        let i = 0;
        i < 8;
        i++
    ) {
        const word =
            words[startWord + i] >>> 0;

        bytes[i * 4] =
            (
                word >>> 24
            ) & 0xff;

        bytes[i * 4 + 1] =
            (
                word >>> 16
            ) & 0xff;

        bytes[i * 4 + 2] =
            (
                word >>> 8
            ) & 0xff;

        bytes[i * 4 + 3] =
            word & 0xff;
    }

    return bytesToHex(bytes);
}


function describeAdapter(gpuAdapter) {
    const info =
        gpuAdapter.info;

    if (info) {
        const parts =
            [
                info.vendor,
                info.architecture,
                info.device,
                info.description,
            ]
                .filter(
                    value =>
                        typeof value === "string" &&
                        value.trim().length > 0
                );

        if (parts.length > 0) {
            return [
                ...new Set(parts)
            ].join(" / ");
        }
    }

    return "WebGPU adapter available (browser did not expose a GPU name)";
}


async function loadShaderModule() {
    const shaderSource =
        await fetch(
            "./photon-miner.wgsl",
            {
                cache: "no-store",
            }
        )
            .then(
                response => {
                    if (!response.ok) {
                        throw new Error(
                            `Could not load photon-miner.wgsl: HTTP ${response.status}`
                        );
                    }

                    return response.text();
                }
            );

    const module =
        device.createShaderModule({
            label:
                "PHOTON WebGPU milestone shader",

            code:
                shaderSource,
        });

    if (
        typeof module.getCompilationInfo ===
        "function"
    ) {
        const compilationInfo =
            await module.getCompilationInfo();

        const errors =
            compilationInfo.messages.filter(
                message =>
                    message.type === "error"
            );

        if (errors.length > 0) {
            throw new Error(
                "WGSL compilation failed:\n" +
                errors
                    .map(
                        message =>
                            `${message.lineNum}:${message.linePos} ${message.message}`
                    )
                    .join("\n")
            );
        }
    }

    return module;
}


async function initializeWebGpu() {
    console.log("[PHOTON] WebGPU opt-in received.");

    if (!window.isSecureContext) {
        throw new Error(
            "This page is not a secure context. Use HTTPS (or localhost for development)."
        );
    }

    if (!("gpu" in navigator)) {
        throw new Error(
            "navigator.gpu is unavailable in this browser/configuration."
        );
    }

    setStatus(
        "Opt-in received. Requesting WebGPU adapter…"
    );

    const freshAdapter =
        await navigator.gpu.requestAdapter({
            powerPreference:
                "high-performance",
        });

    if (!freshAdapter) {
        throw new Error(
            "WebGPU exists, but the browser did not provide a GPU adapter."
        );
    }

    ui.adapterName.textContent =
        describeAdapter(freshAdapter);

    setStatus(
        "Adapter found. Requesting WebGPU device…"
    );

    const freshDevice =
        await freshAdapter.requestDevice();

    adapter =
        freshAdapter;

    device =
        freshDevice;

    const watchedDevice =
        freshDevice;

    watchedDevice.lost.then(
        info =>
            handleWebGpuDeviceLost(
                watchedDevice,
                info
            )
    );

    // Important: do NOT fetch/compile WGSL here.
    // Opt-in should succeed independently of any shader error.
    shaderModule = null;

    setStatus(
        "WebGPU enabled. Ready to run tests."
    );

    setTestButtons(true);

    console.log("[PHOTON] WebGPU enabled.", {
        adapter:
            describeAdapter(adapter),
    });
}


async function ensureShaderModule() {
    if (!device) {
        throw new Error(
            "WebGPU device is not initialized."
        );
    }

    if (!shaderModule) {
        setStatus(
            "Loading and compiling WGSL shader…"
        );

        shaderModule =
            await loadShaderModule();
    }

    return shaderModule;
}



let generatorTableBuffer =
    null;

let generatorTablePromise =
    null;


async function ensureGeneratorTableBuffer() {
    if (generatorTableBuffer) {
        return generatorTableBuffer;
    }

    if (generatorTablePromise) {
        return generatorTablePromise;
    }

    generatorTablePromise =
        (async () => {
            const response =
                await fetch(
                    `../generator-table.bin?v=M67.38-MainContinuousWins-v1`,
                    {
                        cache:
                            "no-store",
                    }
                );

            if (!response.ok) {
                throw new Error(
                    `Failed to fetch generator-table.bin: HTTP ${response.status}`
                );
            }

            const bytes =
                new Uint8Array(
                    await response.arrayBuffer()
                );

            if (bytes.byteLength !== 65536) {
                throw new Error(
                    `Generator table is ${bytes.byteLength} bytes; expected 65536.`
                );
            }

            const buffer =
                device.createBuffer({
                    label:
                        "secp256k1 fixed-base generator table",

                    size:
                        bytes.byteLength,

                    usage:
                        GPUBufferUsage.STORAGE |
                        GPUBufferUsage.COPY_DST,
                });

            device.queue.writeBuffer(
                buffer,
                0,
                bytes
            );

            generatorTableBuffer =
                buffer;

            console.log(
                "[PHOTON] Loaded 64 KiB fixed-base secp256k1 generator table."
            );

            return buffer;
        })();

    try {
        return await generatorTablePromise;
    } finally {
        generatorTablePromise =
            null;
    }
}


function entryPointUsesGeneratorTable(
    entryPoint
) {
    return (
        entryPoint ===
            "photon_integrated_candidate" ||
        entryPoint ===
            "secp256k1_full_scalar_mul_g" ||
        entryPoint ===
            "bch_schnorr_nonce_affine"
    );
}


async function runCompute(
    entryPoint,
    inputData,
    outputWordCount
) {
    await ensureShaderModule();

    const tableBuffer =
        entryPointUsesGeneratorTable(
            entryPoint
        )
            ? await ensureGeneratorTableBuffer()
            : null;

    device.pushErrorScope("validation");
    device.pushErrorScope("internal");

    let scopesPopped =
        false;

    let inputBuffer =
        null;

    let outputBuffer =
        null;

    let readbackBuffer =
        null;

    try {
        inputBuffer =
            device.createBuffer({
                label:
                    `${entryPoint} input`,

                size:
                    inputData.byteLength,

                usage:
                    GPUBufferUsage.STORAGE |
                    GPUBufferUsage.COPY_DST,
            });

        outputBuffer =
            device.createBuffer({
                label:
                    `${entryPoint} output`,

                size:
                    outputWordCount *
                    Uint32Array.BYTES_PER_ELEMENT,

                usage:
                    GPUBufferUsage.STORAGE |
                    GPUBufferUsage.COPY_SRC,
            });

        readbackBuffer =
            device.createBuffer({
                label:
                    `${entryPoint} readback`,

                size:
                    outputWordCount *
                    Uint32Array.BYTES_PER_ELEMENT,

                usage:
                    GPUBufferUsage.COPY_DST |
                    GPUBufferUsage.MAP_READ,
            });

        device.queue.writeBuffer(
            inputBuffer,
            0,
            inputData
        );

        const pipeline =
            device.createComputePipeline({
                label:
                    `${entryPoint} pipeline`,

                layout:
                    "auto",

                compute: {
                    module:
                        shaderModule,

                    entryPoint,
                },
            });

        const bindGroup =
            device.createBindGroup({
                label:
                    `${entryPoint} bind group`,

                layout:
                    pipeline.getBindGroupLayout(0),

                entries: [
                    {
                        binding: 0,
                        resource: {
                            buffer: inputBuffer,
                        },
                    },
                    {
                        binding: 1,
                        resource: {
                            buffer: outputBuffer,
                        },
                    },
                    ...(
                        tableBuffer
                            ? [
                                {
                                    binding: 3,
                                    resource: {
                                        buffer:
                                            tableBuffer,
                                    },
                                },
                            ]
                            : []
                    ),
                ],
            });

        const encoder =
            device.createCommandEncoder({
                label:
                    `${entryPoint} command encoder`,
            });

        const pass =
            encoder.beginComputePass({
                label:
                    `${entryPoint} compute pass`,
            });

        pass.setPipeline(pipeline);
        pass.setBindGroup(0, bindGroup);
        pass.dispatchWorkgroups(1);
        pass.end();

        encoder.copyBufferToBuffer(
            outputBuffer,
            0,
            readbackBuffer,
            0,
            outputWordCount *
                Uint32Array.BYTES_PER_ELEMENT
        );

        device.queue.submit([
            encoder.finish()
        ]);

        await device.queue.onSubmittedWorkDone();

        const internalError =
            await device.popErrorScope();

        const validationError =
            await device.popErrorScope();

        scopesPopped =
            true;

        if (
            validationError ||
            internalError
        ) {
            throw new Error(
                [
                    validationError
                        ? `WebGPU validation error: ${validationError.message}`
                        : null,

                    internalError
                        ? `WebGPU internal error: ${internalError.message}`
                        : null,
                ]
                    .filter(Boolean)
                    .join("\n")
            );
        }

        await readbackBuffer.mapAsync(
            GPUMapMode.READ
        );

        const copied =
            new Uint32Array(
                readbackBuffer.getMappedRange()
            );

        const result =
            new Uint32Array(copied);

        readbackBuffer.unmap();

        return result;

    } finally {
        if (!scopesPopped) {
            try {
                await device.popErrorScope();
            } catch {}

            try {
                await device.popErrorScope();
            } catch {}
        }

        try {
            inputBuffer?.destroy();
        } catch {}

        try {
            outputBuffer?.destroy();
        } catch {}

        try {
            readbackBuffer?.destroy();
        } catch {}
    }
}


function eightWordsBigEndianHex(
    words,
    startWord
) {
    return Array.from(
        words.slice(
            startWord,
            startWord + 8
        ),
        word =>
            (word >>> 0)
                .toString(16)
                .padStart(8, "0")
    ).join("");
}



function hex256ToLittleEndianWords(
    hex
) {
    const normalized =
        hex.toLowerCase();

    if (
        !/^[0-9a-f]{64}$/.test(
            normalized
        )
    ) {
        throw new Error(
            "Expected exactly 32 bytes of hexadecimal scalar data."
        );
    }

    const words =
        new Uint32Array(8);

    for (
        let i = 0;
        i < 8;
        i++
    ) {
        const start =
            64 -
            (i + 1) * 8;

        words[i] =
            Number.parseInt(
                normalized.slice(
                    start,
                    start + 8
                ),
                16
            ) >>> 0;
    }

    return words;
}





let singlePipelineProfilerPipeline =
    null;


async function ensureSinglePipelineProfilerPipeline() {
    await ensureShaderModule();

    if (singlePipelineProfilerPipeline) {
        return singlePipelineProfilerPipeline;
    }

    singlePipelineProfilerPipeline =
        device.createComputePipeline({
            layout:
                "auto",

            compute: {
                module:
                    shaderModule,

                entryPoint:
                    "photon_single_pipeline_profiler",
            },
        });

    return singlePipelineProfilerPipeline;
}


async function runSinglePipelineProfilerDispatch({
    template,
    baseNonce,
    candidateCount,
    stageSelector,
}) {
    if (!device) {
        throw new Error(
            "WebGPU device is not initialized."
        );
    }

    const pipeline =
        await ensureSinglePipelineProfilerPipeline();

    const tableBuffer =
        await ensureGeneratorTableBuffer();

    device.pushErrorScope(
        "validation"
    );

    device.pushErrorScope(
        "internal"
    );

    let inputBuffer;
    let profilerBuffer;

    try {
        const input =
            new Uint32Array(155);

        input.set(
            bytesToBigEndianWords(
                template,
                154
            ),
            0
        );

        // input.byteLength carries the base nonce.
        input[154] =
            baseNonce >>> 0;

        // Byte 615 is outside the 615-byte transaction and is therefore safe
        // as a runtime stage selector. It occupies the low byte of word 153.
        input[153] =
            (
                (
                    input[153] &
                    0xffffff00
                ) |
                (
                    stageSelector &
                    0xff
                )
            ) >>> 0;

        inputBuffer =
            device.createBuffer({
                size:
                    input.byteLength,

                usage:
                    GPUBufferUsage.STORAGE |
                    GPUBufferUsage.COPY_DST,
            });

        device.queue.writeBuffer(
            inputBuffer,
            0,
            input
        );

        profilerBuffer =
            device.createBuffer({
                size:
                    16,

                usage:
                    GPUBufferUsage.STORAGE |
                    GPUBufferUsage.COPY_SRC |
                    GPUBufferUsage.COPY_DST,
            });

        device.queue.writeBuffer(
            profilerBuffer,
            0,
            new Uint32Array(4)
        );

        const bindGroup =
            device.createBindGroup({
                layout:
                    pipeline.getBindGroupLayout(
                        0
                    ),

                entries: [
                    {
                        binding:
                            0,

                        resource: {
                            buffer:
                                inputBuffer,
                        },
                    },
                    {
                        binding:
                            2,

                        resource: {
                            buffer:
                                profilerBuffer,
                        },
                    },
                    {
                        binding:
                            3,

                        resource: {
                            buffer:
                                tableBuffer,
                        },
                    },
                ],
            });

        const encoder =
            device.createCommandEncoder();

        const compute =
            encoder.beginComputePass();

        compute.setPipeline(
            pipeline
        );

        compute.setBindGroup(
            0,
            bindGroup
        );

        compute.dispatchWorkgroups(
            Math.ceil(
                candidateCount /
                32
            )
        );

        compute.end();

        const start =
            performance.now();

        device.queue.submit([
            encoder.finish(),
        ]);

        await device.queue.onSubmittedWorkDone();

        const elapsedMs =
            performance.now() -
            start;

        const internalError =
            await device.popErrorScope();

        const validationError =
            await device.popErrorScope();

        if (internalError) {
            throw new Error(
                `WebGPU internal error: ${internalError.message}`
            );
        }

        if (validationError) {
            throw new Error(
                `WebGPU validation error: ${validationError.message}`
            );
        }

        return {
            elapsedMs,
        };

    } catch (error) {
        try {
            await device.popErrorScope();
        } catch {}

        try {
            await device.popErrorScope();
        } catch {}

        throw error;

    } finally {
        inputBuffer?.destroy();
        profilerBuffer?.destroy();
    }
}


async function runProfilerDispatch({
    entryPoint,
    template,
    baseNonce,
    candidateCount,
}) {
    if (!device) {
        throw new Error(
            "WebGPU device is not initialized."
        );
    }

    await ensureShaderModule();

    const profilerUsesGeneratorTable =
        entryPoint !==
        "photon_profile_a_hash_rfc6979";

    const tableBuffer =
        profilerUsesGeneratorTable
            ? await ensureGeneratorTableBuffer()
            : null;

    device.pushErrorScope(
        "validation"
    );

    device.pushErrorScope(
        "internal"
    );

    let inputBuffer;
    let profilerBuffer;

    try {
        const pipeline =
            device.createComputePipeline({
                layout:
                    "auto",

                compute: {
                    module:
                        shaderModule,

                    entryPoint,
                },
            });

        const input =
            new Uint32Array(155);

        input.set(
            bytesToBigEndianWords(
                template,
                154
            ),
            0
        );

        input[154] =
            baseNonce >>> 0;

        inputBuffer =
            device.createBuffer({
                size:
                    input.byteLength,

                usage:
                    GPUBufferUsage.STORAGE |
                    GPUBufferUsage.COPY_DST,
            });

        device.queue.writeBuffer(
            inputBuffer,
            0,
            input
        );

        profilerBuffer =
            device.createBuffer({
                size:
                    16,

                usage:
                    GPUBufferUsage.STORAGE |
                    GPUBufferUsage.COPY_SRC |
                    GPUBufferUsage.COPY_DST,
            });

        device.queue.writeBuffer(
            profilerBuffer,
            0,
            new Uint32Array(4)
        );

        const bindGroup =
            device.createBindGroup({
                layout:
                    pipeline.getBindGroupLayout(
                        0
                    ),

                entries: [
                    {
                        binding:
                            0,

                        resource: {
                            buffer:
                                inputBuffer,
                        },
                    },
                    {
                        binding:
                            2,

                        resource: {
                            buffer:
                                profilerBuffer,
                        },
                    },
                    ...(
                        tableBuffer
                            ? [
                                {
                                    binding:
                                        3,

                                    resource: {
                                        buffer:
                                            tableBuffer,
                                    },
                                },
                            ]
                            : []
                    ),
                ],
            });

        const encoder =
            device.createCommandEncoder();

        const compute =
            encoder.beginComputePass();

        compute.setPipeline(
            pipeline
        );

        compute.setBindGroup(
            0,
            bindGroup
        );

        compute.dispatchWorkgroups(
            Math.ceil(
                candidateCount /
                32
            )
        );

        compute.end();

        const start =
            performance.now();

        device.queue.submit([
            encoder.finish(),
        ]);

        await device.queue.onSubmittedWorkDone();

        const elapsedMs =
            performance.now() -
            start;

        const internalError =
            await device.popErrorScope();

        const validationError =
            await device.popErrorScope();

        if (internalError) {
            throw new Error(
                `WebGPU internal error: ${internalError.message}`
            );
        }

        if (validationError) {
            throw new Error(
                `WebGPU validation error: ${validationError.message}`
            );
        }

        return {
            elapsedMs,
        };

    } catch (error) {
        try {
            await device.popErrorScope();
        } catch {}

        try {
            await device.popErrorScope();
        } catch {}

        throw error;

    } finally {
        inputBuffer?.destroy();
        profilerBuffer?.destroy();
    }
}



