const PHOTON_PRIVATE_KEY_STORAGE_KEY =
    "photon.minerPrivateKey.v1";

const SECP256K1_N =
    BigInt(
        "0xfffffffffffffffffffffffffffffffebaaedce6af48a03bbfd25e8cd0364141"
    );


function bytesToHexLocal(
    bytes
) {
    return Array.from(
        bytes
    )
        .map(
            value =>
                value
                    .toString(16)
                    .padStart(2, "0")
        )
        .join("");
}


function privateKeyHexIsValid(
    privateKeyHex
) {
    if (
        typeof privateKeyHex !==
            "string" ||
        !/^[0-9a-fA-F]{64}$/.test(
            privateKeyHex
        )
    ) {
        return false;
    }

    const value =
        BigInt(
            `0x${privateKeyHex}`
        );

    return (
        value >
            0n &&
        value <
            SECP256K1_N
    );
}


function createRandomPrivateKeyHex() {
    while (true) {
        const bytes =
            new Uint8Array(
                32
            );

        crypto.getRandomValues(
            bytes
        );

        const privateKeyHex =
            bytesToHexLocal(
                bytes
            );

        if (
            privateKeyHexIsValid(
                privateKeyHex
            )
        ) {
            return privateKeyHex;
        }
    }
}


function getOrCreatePersistentMinerPrivateKey() {
    let existing =
        localStorage.getItem(
            PHOTON_PRIVATE_KEY_STORAGE_KEY
        );

    if (
        existing &&
        privateKeyHexIsValid(
            existing
        )
    ) {
        return {
            privateKeyHex:
                existing.toLowerCase(),

            created:
                false,
        };
    }

    const privateKeyHex =
        createRandomPrivateKeyHex();

    localStorage.setItem(
        PHOTON_PRIVATE_KEY_STORAGE_KEY,
        privateKeyHex
    );

    return {
        privateKeyHex,
        created:
            true,
    };
}


async function deriveCompressedPublicKeyHex(
    privateKeyHex,
    template
) {
    const output =
        await runComputeWithPrivateKey({
            entryPoint:
                "photon_arbitrary_key_candidate",
            template,
            nonce:
                0,
            selector:
                2,
            privateKeyHex,
            outputWordCount:
                16,
        });

    const prefix =
        output[0]
            .toString(16)
            .padStart(2, "0");

    const x =
        Array.from(
            output.slice(
                1,
                9
            )
        )
            .map(
                word =>
                    word
                        .toString(16)
                        .padStart(8, "0")
            )
            .join("");

    return prefix + x;
}


async function shortKeyFingerprint(
    publicKeyHex
) {
    const bytes =
        hexToBytes(
            publicKeyHex
        );

    const digest =
        new Uint8Array(
            await crypto.subtle.digest(
                "SHA-256",
                bytes
            )
        );

    return bytesToHexLocal(
        digest.slice(
            0,
            6
        )
    );
}


async function runComputeWithPrivateKey({
    entryPoint,
    template,
    nonce,
    selector,
    privateKeyHex,
    outputWordCount = 16,
}) {
    if (!device) {
        throw new Error(
            "WebGPU device is not initialized."
        );
    }

    await ensureShaderModule();

    const tableBuffer =
        await ensureGeneratorTableBuffer();

    const templateBytes =
        template instanceof Uint8Array
            ? template
            : hexToBytes(
                template
            );

    const input =
        new Uint32Array(155);

    input.set(
        bytesToBigEndianWords(
            templateBytes,
            154
        ),
        0
    );

    input[154] =
        nonce >>> 0;

    input[153] =
        (
            (
                input[153] &
                0xffffff00
            ) |
            (
                selector &
                0xff
            )
        ) >>> 0;

    const privateKeyBytes =
        hexToBytes(
            privateKeyHex
        );

    if (privateKeyBytes.length !== 32) {
        throw new Error(
            "Private key must be exactly 32 bytes."
        );
    }

    const privateKeyWords =
        bytesToBigEndianWords(
            privateKeyBytes,
            8
        );

    const inputBuffer =
        device.createBuffer({
            size:
                input.byteLength,

            usage:
                GPUBufferUsage.STORAGE |
                GPUBufferUsage.COPY_DST,
        });

    const outputBuffer =
        device.createBuffer({
            size:
                outputWordCount *
                4,

            usage:
                GPUBufferUsage.STORAGE |
                GPUBufferUsage.COPY_SRC,
        });

    const privateKeyBuffer =
        device.createBuffer({
            size:
                32,

            usage:
                GPUBufferUsage.STORAGE |
                GPUBufferUsage.COPY_DST,
        });

    const readBuffer =
        device.createBuffer({
            size:
                outputWordCount *
                4,

            usage:
                GPUBufferUsage.COPY_DST |
                GPUBufferUsage.MAP_READ,
        });

    try {
        device.queue.writeBuffer(
            inputBuffer,
            0,
            input
        );

        device.queue.writeBuffer(
            privateKeyBuffer,
            0,
            privateKeyWords
        );

        const pipeline =
            device.createComputePipeline({
                layout:
                    "auto",

                compute: {
                    module:
                        shaderModule,

                    entryPoint,
                },
            });

        const bindGroup =
            device.createBindGroup({
                layout:
                    pipeline.getBindGroupLayout(
                        0
                    ),

                entries: [
                    {
                        binding:
                            0,
                        resource: {
                            buffer:
                                inputBuffer,
                        },
                    },
                    {
                        binding:
                            1,
                        resource: {
                            buffer:
                                outputBuffer,
                        },
                    },
                    {
                        binding:
                            3,
                        resource: {
                            buffer:
                                tableBuffer,
                        },
                    },
                    {
                        binding:
                            4,
                        resource: {
                            buffer:
                                privateKeyBuffer,
                        },
                    },
                ],
            });

        const encoder =
            device.createCommandEncoder();

        const pass =
            encoder.beginComputePass();

        pass.setPipeline(
            pipeline
        );

        pass.setBindGroup(
            0,
            bindGroup
        );

        pass.dispatchWorkgroups(
            1
        );

        pass.end();

        encoder.copyBufferToBuffer(
            outputBuffer,
            0,
            readBuffer,
            0,
            outputWordCount *
                4
        );

        device.queue.submit([
            encoder.finish(),
        ]);

        await device.queue.onSubmittedWorkDone();

        await readBuffer.mapAsync(
            GPUMapMode.READ
        );

        const result =
            new Uint32Array(
                readBuffer
                    .getMappedRange()
                    .slice(0)
            );

        readBuffer.unmap();

        return result;

    } finally {
        inputBuffer.destroy();
        outputBuffer.destroy();
        privateKeyBuffer.destroy();
        readBuffer.destroy();
    }
}


async function runSustainedSearchDispatch({
    template,
    baseNonce,
    candidateCount,
    easyTargetMode,
}) {
    if (!device) {
        throw new Error(
            "WebGPU device is not initialized."
        );
    }

    const pipeline =
        await ensureSustainedSearchPipeline();

    const tableBuffer =
        await ensureGeneratorTableBuffer();

    device.pushErrorScope(
        "validation"
    );

    device.pushErrorScope(
        "internal"
    );

    let inputBuffer;
    let resultBuffer;
    let readbackBuffer;

    try {
        const input =
            new Uint32Array(155);

        input.set(
            bytesToBigEndianWords(
                template,
                154
            ),
            0
        );

        // Base nonce.
        input[154] =
            baseNonce >>> 0;

        // Byte 615 is outside the 615-byte transaction. Use bit 0 as easy-target
        // validation mode flag.
        input[153] =
            (
                (
                    input[153] &
                    0xffffff00
                ) |
                (
                    easyTargetMode
                        ? 1
                        : 0
                )
            ) >>> 0;

        inputBuffer =
            device.createBuffer({
                size:
                    input.byteLength,

                usage:
                    GPUBufferUsage.STORAGE |
                    GPUBufferUsage.COPY_DST,
            });

        device.queue.writeBuffer(
            inputBuffer,
            0,
            input
        );

        // checksum, completed, winners, firstWinnerNoncePlusOne
        resultBuffer =
            device.createBuffer({
                size:
                    16,

                usage:
                    GPUBufferUsage.STORAGE |
                    GPUBufferUsage.COPY_SRC |
                    GPUBufferUsage.COPY_DST,
            });

        device.queue.writeBuffer(
            resultBuffer,
            0,
            new Uint32Array(4)
        );

        readbackBuffer =
            device.createBuffer({
                size:
                    16,

                usage:
                    GPUBufferUsage.COPY_DST |
                    GPUBufferUsage.MAP_READ,
            });

        const bindGroup =
            device.createBindGroup({
                layout:
                    pipeline.getBindGroupLayout(
                        0
                    ),

                entries: [
                    {
                        binding:
                            0,

                        resource: {
                            buffer:
                                inputBuffer,
                        },
                    },
                    {
                        binding:
                            2,

                        resource: {
                            buffer:
                                resultBuffer,
                        },
                    },
                    {
                        binding:
                            3,

                        resource: {
                            buffer:
                                tableBuffer,
                        },
                    },
                ],
            });

        const encoder =
            device.createCommandEncoder();

        const compute =
            encoder.beginComputePass();

        compute.setPipeline(
            pipeline
        );

        compute.setBindGroup(
            0,
            bindGroup
        );

        compute.dispatchWorkgroups(
            Math.ceil(
                candidateCount /
                32
            )
        );

        compute.end();

        encoder.copyBufferToBuffer(
            resultBuffer,
            0,
            readbackBuffer,
            0,
            16
        );

        const start =
            performance.now();

        device.queue.submit([
            encoder.finish(),
        ]);

        await device.queue.onSubmittedWorkDone();

        const elapsedMs =
            performance.now() -
            start;

        await readbackBuffer.mapAsync(
            GPUMapMode.READ
        );

        const resultWords =
            new Uint32Array(
                readbackBuffer
                    .getMappedRange()
                    .slice(0)
            );

        readbackBuffer.unmap();

        const internalError =
            await device.popErrorScope();

        const validationError =
            await device.popErrorScope();

        if (internalError) {
            throw new Error(
                `WebGPU internal error: ${internalError.message}`
            );
        }

        if (validationError) {
            throw new Error(
                `WebGPU validation error: ${validationError.message}`
            );
        }

        return {
            elapsedMs,

            checksum:
                resultWords[0] >>> 0,

            completed:
                resultWords[1] >>> 0,

            winners:
                resultWords[2] >>> 0,

            firstWinnerNonce:
                resultWords[3] === 0
                    ? null
                    : (
                        resultWords[3] -
                        1
                    ) >>> 0,
        };

    } catch (error) {
        try {
            await device.popErrorScope();
        } catch {}

        try {
            await device.popErrorScope();
        } catch {}

        throw error;

    } finally {
        inputBuffer?.destroy();
        resultBuffer?.destroy();
        readbackBuffer?.destroy();
    }
}


async function runPhotonBenchmarkDispatch({
    template,
    baseNonce,
    candidateCount
}) {
    if (
        !device
    ) {
        throw new Error(
            "WebGPU device is not initialized."
        );
    }

    await ensureShaderModule();

    const tableBuffer =
        await ensureGeneratorTableBuffer();

    device.pushErrorScope(
        "validation"
    );

    device.pushErrorScope(
        "internal"
    );

    let inputBuffer;
    let benchmarkBuffer;

    try {
        const pipeline =
            device.createComputePipeline({
                layout:
                    "auto",

                compute: {
                    module:
                        shaderModule,

                    entryPoint:
                        "photon_parallel_benchmark",
                },
            });

        const input =
            new Uint32Array(155);

        input.set(
            bytesToBigEndianWords(
                template,
                154
            ),
            0
        );

        // input.byteLength carries base nonce for this benchmark entrypoint.
        input[154] =
            baseNonce >>> 0;

        // Unused byte 615 stores candidate count as a diagnostic guard only.
        input[153] =
            (
                (
                    input[153] &
                    0xffffff00
                ) |
                (
                    Math.min(
                        candidateCount,
                        255
                    ) &
                    0xff
                )
            ) >>> 0;

        inputBuffer =
            device.createBuffer({
                size:
                    input.byteLength,

                usage:
                    GPUBufferUsage.STORAGE |
                    GPUBufferUsage.COPY_DST,
            });

        device.queue.writeBuffer(
            inputBuffer,
            0,
            input
        );

        // 4 x atomic<u32>:
        // checksum, completed, winners, firstWinnerNoncePlusOne
        benchmarkBuffer =
            device.createBuffer({
                size:
                    16,

                usage:
                    GPUBufferUsage.STORAGE |
                    GPUBufferUsage.COPY_SRC |
                    GPUBufferUsage.COPY_DST,
            });

        device.queue.writeBuffer(
            benchmarkBuffer,
            0,
            new Uint32Array(4)
        );

        const bindGroup =
            device.createBindGroup({
                layout:
                    pipeline.getBindGroupLayout(
                        0
                    ),

                entries: [
                    {
                        binding:
                            0,

                        resource: {
                            buffer:
                                inputBuffer,
                        },
                    },
                    {
                        binding:
                            2,

                        resource: {
                            buffer:
                                benchmarkBuffer,
                        },
                    },
                    {
                        binding:
                            3,

                        resource: {
                            buffer:
                                tableBuffer,
                        },
                    },
                ],
            });

        const encoder =
            device.createCommandEncoder();

        const pass =
            encoder.beginComputePass();

        pass.setPipeline(
            pipeline
        );

        pass.setBindGroup(
            0,
            bindGroup
        );

        // WGSL workgroup size is 32.
        pass.dispatchWorkgroups(
            Math.ceil(
                candidateCount /
                32
            )
        );

        pass.end();

        const start =
            performance.now();

        device.queue.submit([
            encoder.finish(),
        ]);

        await device.queue.onSubmittedWorkDone();

        const end =
            performance.now();

        const internalError =
            await device.popErrorScope();

        const validationError =
            await device.popErrorScope();

        if (internalError) {
            throw new Error(
                `WebGPU internal error: ${internalError.message}`
            );
        }

        if (validationError) {
            throw new Error(
                `WebGPU validation error: ${validationError.message}`
            );
        }

        return {
            elapsedMs:
                end -
                start,
        };

    } catch (
        error
    ) {
        // Pop any scopes that remain if an exception happened before normal pop.
        try {
            await device.popErrorScope();
        } catch {}

        try {
            await device.popErrorScope();
        } catch {}

        throw error;

    } finally {
        inputBuffer?.destroy();
        benchmarkBuffer?.destroy();
    }
}



