// ============================================================================
// M67.28 — isolate actual M45 Stage-B correctness from scalable C1 codegen.
//  1) Run corrected CPU-M27 Stage A + exact production M45 B4a/b/c/d.
//  2) Read candidate-0 Jacobian and compare its affine point to strict CPU kG.
//  3) Run an exact M67.19-style WG1 C1 directly on that GPU-produced record.
//  4) Sweep scalable C1 baseline workgroup sizes 1/8/16/32/64, then fixed-d
//     at the largest baseline workgroup size that passes.
// No C2/C3 hashing is involved in this diagnostic.
// ============================================================================

async function m6728RunAB(runtime, baseNonce) {
    m50WriteBaseNonce(runtime, baseNonce);
    const encoder = device.createCommandEncoder({label:'M67.28 A+M45 encoder'});
    let pass = encoder.beginComputePass({label:'M67.28 A'});
    pass.setPipeline(runtime.a);
    pass.setBindGroup(0, runtime.bindA);
    pass.dispatchWorkgroups(runtime.candidateCount / 128);
    pass.end();
    for (let i=0;i<runtime.bPipelines.length;i+=1) {
        pass = encoder.beginComputePass({label:`M67.28 B4${String.fromCharCode(97+i)}`});
        pass.setPipeline(runtime.bPipelines[i]);
        pass.setBindGroup(0, runtime.bGroups[i]);
        pass.dispatchWorkgroups(runtime.candidateCount / 32);
        pass.end();
    }
    device.queue.submit([encoder.finish()]);
    await device.queue.onSubmittedWorkDone();
}

async function m6728ReadSignatureBuffer(buffer) {
    const rb=device.createBuffer({size:64,usage:GPUBufferUsage.COPY_DST|GPUBufferUsage.MAP_READ});
    try {
        const enc=device.createCommandEncoder();
        enc.copyBufferToBuffer(buffer,0,rb,0,64);
        device.queue.submit([enc.finish()]);
        await device.queue.onSubmittedWorkDone();
        await rb.mapAsync(GPUMapMode.READ);
        const words=Array.from(new Uint32Array(rb.getMappedRange().slice(0)));
        rb.unmap();
        return m53GpuSignatureHex(words).toLowerCase();
    } finally { rb.destroy(); }
}

async function m6728RunProvenWg1(runtime) {
    const pipeline=await m6726CreateValidatedPipeline('C1-proven-wg1','photon_m6728_c1_proven_wg1');
    const out=device.createBuffer({size:64,usage:GPUBufferUsage.STORAGE|GPUBufferUsage.COPY_SRC});
    try {
        const bind=await m6726CreateValidatedBindGroup('C1-proven-wg1',pipeline,[
            {binding:0,resource:{buffer:runtime.state.inputBuffer}},
            {binding:1,resource:{buffer:out}},
            {binding:4,resource:{buffer:runtime.state.privateBuffer}},
            {binding:10,resource:{buffer:runtime.state.intermediate}},
        ]);
        const enc=device.createCommandEncoder(); const pass=enc.beginComputePass();
        pass.setPipeline(pipeline); pass.setBindGroup(0,bind); pass.dispatchWorkgroups(1); pass.end();
        device.queue.submit([enc.finish()]); await device.queue.onSubmittedWorkDone();
        return await m6728ReadSignatureBuffer(out);
    } finally {out.destroy();}
}

async function m6728RunScalableC1(runtime, entryPoint, wg, fixedD=false) {
    const pipeline=await m6726CreateValidatedPipeline(entryPoint,entryPoint);
    const sig=device.createBuffer({size:runtime.candidateCount*64,usage:GPUBufferUsage.STORAGE|GPUBufferUsage.COPY_SRC});
    try {
        const entries=[
            {binding:0,resource:{buffer:runtime.state.inputBuffer}},
            {binding:10,resource:{buffer:runtime.state.intermediate}},
            {binding:13,resource:{buffer:sig}},
        ];
        if (fixedD) entries.push({binding:11,resource:{buffer:m39FixedDTableBuffer}});
        else entries.push({binding:4,resource:{buffer:runtime.state.privateBuffer}});
        const bind=await m6726CreateValidatedBindGroup(entryPoint,pipeline,entries);
        const enc=device.createCommandEncoder(); const pass=enc.beginComputePass();
        pass.setPipeline(pipeline); pass.setBindGroup(0,bind);
        pass.dispatchWorkgroups(Math.ceil(runtime.candidateCount/wg)); pass.end();
        device.queue.submit([enc.finish()]); await device.queue.onSubmittedWorkDone();
        return await m6728ReadSignatureBuffer(sig);
    } finally {sig.destroy();}
}

async function runM6728C1Isolation() {
    if (!device) throw new Error('Enable WebGPU before running M67.28.');
    if (ui.runOneGpuCpuSolution) ui.runOneGpuCpuSolution.disabled=true;
    if (ui.armLiveBroadcast) ui.armLiveBroadcast.checked=false;
    let runtime=null;
    try {
        setStatus('M67.28 checking actual M45 Jacobian, then C1 workgroup-size ladder...');
        setResult(ui.m53HardwareResult,['RUNNING - M45 + C1 WORKGROUP ISOLATION','','64 MiB table: ENABLED','C2/C3: SKIPPED','Live network/broadcast: DISABLED'].join('\n'),'');
        const keyState=getOrCreatePersistentMinerPrivateKey();
        const fixtureTemplate=hexToBytes(PHOTON_VECTOR.photonIntegratedCandidate.unsignedTemplateHex);
        const personalized=await m56TemplateForPrivateKey({fixtureTemplate,privateKeyHex:keyState.privateKeyHex});
        const template=personalized.template.slice();
        const batonStart=locatePhotonBatonStart(template);
        const targetBytes=new Uint8Array(32); targetBytes[31]=0x04; template.set(targetBytes,batonStart+4);
        const nonce=0x4de00123;
        await createM27PrecomputedState(keyState.privateKeyHex,{transferMode:'cpu-generated'});
        await createM39FixedDTable(keyState.privateKeyHex);
        await ensureM29TableBuffer(16);
        runtime=await m6724CreateRuntime({template,privateKeyHex:keyState.privateKeyHex,candidateCount:128,baseNonce:nonce,c1Mode:'baseline'});
        await m6728RunAB(runtime,nonce);
        const rec=await m6713ReadIntermediateRecord0(runtime.state);
        const target=template.slice(batonStart+4,batonStart+36);
        const cpuMsg=await sha256BytesBrowser(concatBytes(uint32LE(nonce),target));
        const cpuK=await cpuBchRfc6979Nonce(hexToBytes(keyState.privateKeyHex),cpuMsg);
        const cpuPoint=cpuScalarMultiply(cpuK);
        const stageAMsgMatch=rec.messageHashHex===bytesToHexLocal(cpuMsg).toLowerCase();
        const stageAKMatch=rec.kHex===cpuK.toString(16).padStart(64,'0').toLowerCase();
        const m45PointMatch=m6714PointMatch(rec,cpuPoint);
        const cpu=await m53CpuCandidate({template,nonce,privateKeyHex:keyState.privateKeyHex});
        const cpuSig=cpu.signatureHex.toLowerCase();

        const provenSig=await m6728RunProvenWg1(runtime);
        const provenMatch=provenSig===cpuSig;
        const widths=[1,8,16,32,64];
        const baseline=[];
        for (const wg of widths) {
            const sig=await m6728RunScalableC1(runtime,`photon_m6728_c1_baseline_wg${wg}`,wg,false);
            baseline.push({wg,sig,match:sig===cpuSig});
        }
        const passing=baseline.filter(r=>r.match).map(r=>r.wg);
        const best=passing.length?Math.max(...passing):null;
        let fixed=null;
        if (best!==null) {
            const sig=await m6728RunScalableC1(runtime,`photon_m6728_c1_fixed_wg${best}`,best,true);
            fixed={wg:best,sig,match:sig===cpuSig};
        }
        let diagnosis='';
        if (!stageAMsgMatch || !stageAKMatch) diagnosis='Unexpected regression before Stage B: Stage A no longer matches strict CPU.';
        else if (!m45PointMatch) diagnosis='FIRST REAL FULL-PIPELINE BREAKPOINT: M45 four-pass Stage B produces the wrong affine kG point on Apple. C1 is downstream; isolate the four M45 passes next.';
        else if (!provenMatch) diagnosis='M45 kG is correct, but even the exact proven WG1 C1 fails when consuming the GPU-produced M45 Jacobian representation. Compare M45 Jacobian representation/normalization with the CPU-injected Z=1 point.';
        else if (best===null) diagnosis='M45 and exact WG1 C1 are correct, but every scalable binding-13 C1 variant fails. Focus on scalable signature storage/binding representation rather than workgroup size.';
        else if (best<64) diagnosis=`M45 is correct and C1 correctness is workgroup-size sensitive on Apple. Largest passing baseline workgroup is ${best}; use that size for Apple and benchmark it.`;
        else diagnosis='M45 and scalable WG64 baseline C1 both match. M67.27 failure was specific to its C1 implementation/runtime; compare generated entry-point code and fixed-d path.';
        const overall=stageAMsgMatch&&stageAKMatch&&m45PointMatch&&provenMatch&&best!==null;
        const lines=[
            overall?'PASS - M45/C1 ISOLATION FOUND A CORRECT SCALABLE C1 PATH.':'FAIL - M45/C1 ISOLATION FOUND THE NEXT BREAKPOINT.',
            '',`Test version: M67.38-MainContinuousWins-v1`,'Adapter: '+(adapter?describeAdapter(adapter):'unknown'),'',
            'Stage A:',`messageHash = CPU: ${stageAMsgMatch?'MATCH':'MISMATCH'}`,`k = CPU: ${stageAKMatch?'MATCH':'MISMATCH'}`,'',
            'Actual production M45 B4a/b/c/d output:',`Jacobian X zero: ${rec.xZero?'YES':'NO'}`,`Jacobian Y zero: ${rec.yZero?'YES':'NO'}`,`Jacobian Z zero: ${rec.zZero?'YES':'NO'}`,`CPU-affine(kG) = M45-affine(point): ${m45PointMatch?'MATCH':'MISMATCH'}`,'',
            'Exact proven M67.19-style C1 on that M45 record:',`signature = CPU: ${provenMatch?'MATCH':'MISMATCH'}`,'',
            'Scalable baseline C1 workgroup ladder:',...baseline.map(r=>`WG${r.wg}: signature=${r.match?'MATCH':'MISMATCH'}`),`Largest passing WG: ${best===null?'NONE':best}`,'',
            'Fixed-d check at largest passing baseline WG:',fixed?`WG${fixed.wg}: signature=${fixed.match?'MATCH':'MISMATCH'}`:'Not run - no scalable baseline WG passed','',
            'Interpretation:',diagnosis,'',
            'Safety:','Electrum queried: NO','Live PHOTON target mined: NO','Broadcast RPC called: NO','Private key transmitted: NO'
        ];
        setResult(ui.m53HardwareResult,lines.join('\n'),overall?'pass':'fail');
        setStatus(overall?'M67.28 found a correct scalable C1 path.':'M67.28 isolated the next breakpoint.');
        m673RefreshDiagnosticReport();
        return {overall,stageAMsgMatch,stageAKMatch,m45PointMatch,provenMatch,baseline,fixed,diagnosis};
    } finally {runtime?.destroy?.(); if(ui.runOneGpuCpuSolution)ui.runOneGpuCpuSolution.disabled=false;}
}


// ============================================================================
// M67.29 — test whether canonicalizing the actual M45 Jacobian representation
// repairs the otherwise-proven C1 on Apple/Metal.
// ============================================================================
async function m6729RunSharedOutputC1(runtime, entryPoint) {
    const pipeline=await m6726CreateValidatedPipeline(entryPoint,entryPoint);
    const out=device.createBuffer({size:64,usage:GPUBufferUsage.STORAGE|GPUBufferUsage.COPY_SRC});
    try {
        const bind=await m6726CreateValidatedBindGroup(entryPoint,pipeline,[
            {binding:0,resource:{buffer:runtime.state.inputBuffer}},
            {binding:1,resource:{buffer:out}},
            {binding:4,resource:{buffer:runtime.state.privateBuffer}},
            {binding:10,resource:{buffer:runtime.state.intermediate}},
        ]);
        const enc=device.createCommandEncoder(); const pass=enc.beginComputePass();
        pass.setPipeline(pipeline); pass.setBindGroup(0,bind); pass.dispatchWorkgroups(1); pass.end();
        device.queue.submit([enc.finish()]); await device.queue.onSubmittedWorkDone();
        return await m6728ReadSignatureBuffer(out);
    } finally {out.destroy();}
}

async function m6729RunStorageC1(runtime, entryPoint) {
    return await m6728RunScalableC1(runtime,entryPoint,64,false);
}

async function runM6729NormalizationIsolation() {
    if (!device) throw new Error('Enable WebGPU before running M67.29.');
    if (ui.runOneGpuCpuSolution) ui.runOneGpuCpuSolution.disabled=true;
    if (ui.armLiveBroadcast) ui.armLiveBroadcast.checked=false;
    let runtime=null;
    try {
        setStatus('M67.29 testing normalization of the actual M45 Jacobian point...');
        setResult(ui.m53HardwareResult,['RUNNING - M45 JACOBIAN NORMALIZATION ISOLATION','','64 MiB table: ENABLED','Live network/broadcast: DISABLED'].join('\n'),'');
        const keyState=getOrCreatePersistentMinerPrivateKey();
        const fixtureTemplate=hexToBytes(PHOTON_VECTOR.photonIntegratedCandidate.unsignedTemplateHex);
        const personalized=await m56TemplateForPrivateKey({fixtureTemplate,privateKeyHex:keyState.privateKeyHex});
        const template=personalized.template.slice();
        const batonStart=locatePhotonBatonStart(template);
        const targetBytes=new Uint8Array(32); targetBytes[31]=0x04; template.set(targetBytes,batonStart+4);
        const nonce=0x4df00123;
        await createM27PrecomputedState(keyState.privateKeyHex,{transferMode:'cpu-generated'});
        await ensureM29TableBuffer(16);
        runtime=await m6724CreateRuntime({template,privateKeyHex:keyState.privateKeyHex,candidateCount:128,baseNonce:nonce,c1Mode:'baseline'});
        await m6728RunAB(runtime,nonce);
        const rec=await m6713ReadIntermediateRecord0(runtime.state);
        const cpu=await m53CpuCandidate({template,nonce,privateKeyHex:keyState.privateKeyHex});
        const cpuSig=cpu.signatureHex.toLowerCase();
        const P=M22_SECP_P;
        const rawX=BigInt('0x'+rec.xHex), rawY=BigInt('0x'+rec.yHex), rawZ=BigInt('0x'+rec.zHex);
        const canonical={x:rawX<P,y:rawY<P,z:rawZ<P};
        const target=template.slice(batonStart+4,batonStart+36);
        const cpuMsg=await sha256BytesBrowser(concatBytes(uint32LE(nonce),target));
        const cpuK=await cpuBchRfc6979Nonce(hexToBytes(keyState.privateKeyHex),cpuMsg);
        const m45PointMatch=m6714PointMatch(rec,cpuScalarMultiply(cpuK));

        const rawSig=await m6728RunProvenWg1(runtime);
        const variants=[
            {name:'normalize Z + binary inverse', ep:'photon_m6729_c1_znorm_wg1', ep64:'photon_m6729_c1_znorm_wg64'},
            {name:'normalize X/Y/Z + binary inverse', ep:'photon_m6729_c1_xyznorm_wg1', ep64:'photon_m6729_c1_xyznorm_wg64'},
            {name:'normalize Z + Fermat inverse', ep:'photon_m6729_c1_znorm_fermat_wg1', ep64:'photon_m6729_c1_znorm_fermat_wg64'},
        ];
        for (const v of variants) {
            v.sig=await m6729RunSharedOutputC1(runtime,v.ep);
            v.match=v.sig===cpuSig;
            v.wg64Match=null;
            if(v.match){
                const sig64=await m6729RunStorageC1(runtime,v.ep64);
                v.wg64Sig=sig64; v.wg64Match=sig64===cpuSig;
            }
        }
        const passing=variants.filter(v=>v.match);
        let diagnosis;
        if(!m45PointMatch) diagnosis='Unexpected regression: M45 affine point no longer matches CPU.';
        else if(rawSig===cpuSig) diagnosis='Unexpected: raw C1 now matches; rerun to check reproducibility.';
        else if(variants[0].match) diagnosis='CONFIRMED: raw M45 Z representation is the issue. normalize_field(Z) before field_inv_binary repairs C1; this is a very cheap Apple fix.';
        else if(variants[1].match) diagnosis='Normalizing Z alone is insufficient, but canonicalizing X/Y/Z repairs C1. Use component canonicalization at the B→C handoff.';
        else if(variants[2].match) diagnosis='Canonicalization alone does not repair binary inversion, but normalized-Z Fermat inversion works. Apple needs the alternate inversion path for M45 Jacobian Z.';
        else diagnosis='None of the canonicalization/inversion variants repairs actual M45 C1. Next isolate raw M45 Z inversion and affine-X intermediates directly against CPU.';
        const overall=passing.length>0;
        const lines=[
            overall?'PASS - M45 JACOBIAN NORMALIZATION FOUND A CORRECT C1 PATH.':'FAIL - M45 JACOBIAN NORMALIZATION DID NOT REPAIR C1.',
            '', 'Test version: M67.38-MainContinuousWins-v1','Adapter: '+(adapter?describeAdapter(adapter):'unknown'),'',
            'Actual M45 point:',`affine kG = CPU: ${m45PointMatch?'MATCH':'MISMATCH'}`,`raw X canonical (<p): ${canonical.x?'YES':'NO'}`,`raw Y canonical (<p): ${canonical.y?'YES':'NO'}`,`raw Z canonical (<p): ${canonical.z?'YES':'NO'}`,
            `raw Z: ${rec.zHex}`,'',
            'Raw proven C1:',`signature = CPU: ${rawSig===cpuSig?'MATCH':'MISMATCH'}`,'',
            'Normalization / inversion matrix:',
            ...variants.flatMap(v=>[`${v.name}: WG1 signature=${v.match?'MATCH':'MISMATCH'}`,v.match?`  WG64 signature=${v.wg64Match?'MATCH':'MISMATCH'}`:'  WG64: not run']),
            '', 'Interpretation:',diagnosis,'',
            'Safety:','Electrum queried: NO','Live PHOTON target mined: NO','Broadcast RPC called: NO','Private key transmitted: NO'
        ];
        setResult(ui.m53HardwareResult,lines.join('\n'),overall?'pass':'fail');
        setStatus(overall?'M67.29 found a normalized C1 path.':'M67.29 normalization matrix did not repair C1.');
        m673RefreshDiagnosticReport();
        return {overall,canonical,variants,diagnosis};
    } finally {runtime?.destroy?.(); if(ui.runOneGpuCpuSolution)ui.runOneGpuCpuSolution.disabled=false;}
}


// ============================================================================
// M67.31 — Apple/Metal submission-boundary matrix.
//
// M67.29's exact normalized-Z WG64 C1 passed only after A/M45 had completed in
// a prior queue submission. M67.23's C2 likewise ran after C1 in a separate
// submission. This test keeps the exact passing M67.29 C1 entry point and
// varies only command-buffer / queue-submission boundaries.
// ============================================================================
async function m6731UseExactPassingC1(runtime) {
    const pipeline = await m6726CreateValidatedPipeline(
        'M67.31 exact-M67.29 normalized C1',
        'photon_m6729_c1_znorm_wg64'
    );
    const bind = await m6726CreateValidatedBindGroup(
        'M67.31 exact-M67.29 normalized C1',
        pipeline,
        [
            { binding: 0, resource: { buffer: runtime.state.inputBuffer } },
            { binding: 4, resource: { buffer: runtime.state.privateBuffer } },
            { binding: 10, resource: { buffer: runtime.state.intermediate } },
            { binding: 13, resource: { buffer: runtime.signatureBuffer } },
        ]
    );
    runtime.c1 = pipeline;
    runtime.bindC1 = bind;
}

function m6731EncodeStages(runtime, stages, copyResult) {
    const encoder = device.createCommandEncoder({
        label: `M67.31 ${stages.join('+')} encoder`,
    });
    let pass;
    if (stages.includes('A')) {
        pass = encoder.beginComputePass({ label: 'M67.31 A' });
        pass.setPipeline(runtime.a);
        pass.setBindGroup(0, runtime.bindA);
        pass.dispatchWorkgroups(runtime.candidateCount / 128);
        pass.end();
    }
    if (stages.includes('B')) {
        for (let i = 0; i < runtime.bPipelines.length; i += 1) {
            pass = encoder.beginComputePass({ label: `M67.31 B4${String.fromCharCode(97+i)}` });
            pass.setPipeline(runtime.bPipelines[i]);
            pass.setBindGroup(0, runtime.bGroups[i]);
            pass.dispatchWorkgroups(runtime.candidateCount / 32);
            pass.end();
        }
    }
    if (stages.includes('C1')) {
        pass = encoder.beginComputePass({ label: 'M67.31 C1 exact normalized' });
        pass.setPipeline(runtime.c1);
        pass.setBindGroup(0, runtime.bindC1);
        pass.dispatchWorkgroups(runtime.candidateCount / 64);
        pass.end();
    }
    if (stages.includes('C2')) {
        pass = encoder.beginComputePass({ label: 'M67.31 C2 HASH256' });
        pass.setPipeline(runtime.c2);
        pass.setBindGroup(0, runtime.bindC2);
        pass.dispatchWorkgroups(runtime.candidateCount / 64);
        pass.end();
    }
    if (stages.includes('C3')) {
        pass = encoder.beginComputePass({ label: 'M67.31 C3 winner' });
        pass.setPipeline(runtime.c3);
        pass.setBindGroup(0, runtime.bindC3);
        pass.dispatchWorkgroups(runtime.candidateCount / 64);
        pass.end();
    }
    if (copyResult) {
        encoder.copyBufferToBuffer(
            runtime.state.resultBuffer, 0,
            runtime.state.readback, 0,
            16
        );
    }
    return encoder.finish();
}

async function m6731RunGroups(runtime, baseNonce, groups, waitBetween) {
    m50WriteBaseNonce(runtime, baseNonce);
    m38ResetResult(runtime.state);
    device.queue.writeBuffer(runtime.state.readback, 0, new Uint32Array(4));
    const started = performance.now();
    for (let i = 0; i < groups.length; i += 1) {
        const command = m6731EncodeStages(runtime, groups[i], i === groups.length - 1);
        device.queue.submit([command]);
        if (waitBetween && i < groups.length - 1) {
            await device.queue.onSubmittedWorkDone();
        }
    }
    await device.queue.onSubmittedWorkDone();
    const elapsedMs = performance.now() - started;
    await runtime.state.readback.mapAsync(GPUMapMode.READ);
    const resultWords = Array.from(new Uint32Array(runtime.state.readback.getMappedRange().slice(0)));
    runtime.state.readback.unmap();
    return {
        elapsedMs,
        completed: resultWords[1] >>> 0,
        winners: resultWords[2] >>> 0,
        firstWinnerNonce: resultWords[3] === 0 ? null : ((resultWords[3] - 1) >>> 0),
    };
}

async function m6731RunMode({ template, privateKeyHex, nonce, mode }) {
    const runtime = await m6724CreateRuntime({
        template,
        privateKeyHex,
        candidateCount: 128,
        baseNonce: nonce,
        c1Mode: 'baseline',
    });
    try {
        await m6731UseExactPassingC1(runtime);
        const result = await m6731RunGroups(
            runtime,
            nonce,
            mode.groups,
            mode.waitBetween
        );
        const gpu = await m6724ReadCandidateOutputs(runtime);
        const cpu = await m53CpuCandidate({ template, nonce, privateKeyHex });
        return {
            name: mode.name,
            groups: mode.groups,
            waitBetween: mode.waitBetween,
            elapsedMs: result.elapsedMs,
            completed: result.completed,
            signatureMatch: gpu.signatureHex === cpu.signatureHex.toLowerCase(),
            batchHashMatch: gpu.storedBatchHashHex === cpu.hashHex.toLowerCase(),
            replayHashMatch: gpu.hashHex === cpu.hashHex.toLowerCase(),
            gpuSignatureHex: gpu.signatureHex,
            gpuBatchHashHex: gpu.storedBatchHashHex,
            cpuSignatureHex: cpu.signatureHex.toLowerCase(),
            cpuHashHex: cpu.hashHex.toLowerCase(),
        };
    } finally {
        runtime.destroy();
    }
}

async function runM6731SubmissionBoundaryMatrix() {
    if (!device) throw new Error('Enable WebGPU before running M67.31.');
    if (ui.runOneGpuCpuSolution) ui.runOneGpuCpuSolution.disabled = true;
    if (ui.armLiveBroadcast) ui.armLiveBroadcast.checked = false;
    try {
        setStatus('M67.31 testing Apple queue-submission boundaries at M45→C1→C2...');
        setResult(ui.m53HardwareResult, [
            'RUNNING - APPLE SUBMISSION-BOUNDARY MATRIX', '',
            'Exact passing M67.29 normalized-Z WG64 C1: YES',
            '64 MiB Stage-B table: ENABLED',
            'CPU crypto between GPU stages: NO',
            'Live network/broadcast: DISABLED',
        ].join('\n'), '');

        const keyState = getOrCreatePersistentMinerPrivateKey();
        const fixtureTemplate = hexToBytes(PHOTON_VECTOR.photonIntegratedCandidate.unsignedTemplateHex);
        const personalized = await m56TemplateForPrivateKey({
            fixtureTemplate,
            privateKeyHex: keyState.privateKeyHex,
        });
        const template = personalized.template.slice();
        const batonStart = locatePhotonBatonStart(template);
        const targetBytes = new Uint8Array(32);
        targetBytes[31] = 0x04;
        template.set(targetBytes, batonStart + 4);
        const nonce = 0x4e000123;

        await createM27PrecomputedState(keyState.privateKeyHex, { transferMode: 'cpu-generated' });
        await ensureM29TableBuffer(16);
        await createM30TxPrefixState(template);

        const modes = [
            {
                name: '1 submit: A+B+C1+C2+C3',
                groups: [['A','B','C1','C2','C3']],
                waitBetween: false,
            },
            {
                name: '2 submits queued: A+B | C1+C2+C3',
                groups: [['A','B'],['C1','C2','C3']],
                waitBetween: false,
            },
            {
                name: '3 submits queued: A+B | C1 | C2+C3',
                groups: [['A','B'],['C1'],['C2','C3']],
                waitBetween: false,
            },
            {
                name: '4 submits queued: A+B | C1 | C2 | C3',
                groups: [['A','B'],['C1'],['C2'],['C3']],
                waitBetween: false,
            },
            {
                name: '3 submits + CPU waits: A+B | C1 | C2+C3',
                groups: [['A','B'],['C1'],['C2','C3']],
                waitBetween: true,
            },
        ];

        const rows = [];
        for (const mode of modes) {
            rows.push(await m6731RunMode({
                template,
                privateKeyHex: keyState.privateKeyHex,
                nonce,
                mode,
            }));
        }

        const passing = rows.filter(r => r.signatureMatch && r.batchHashMatch && r.completed === 128);
        const queuedPassing = passing.filter(r => !r.waitBetween);
        let diagnosis;
        if (rows[0].signatureMatch && rows[0].batchHashMatch) {
            diagnosis = 'Unexpected: the single-submission path now passes. Re-run for reproducibility before changing production.';
        } else if (queuedPassing.length) {
            diagnosis = `CONFIRMED: Apple needs queue submission boundaries, but no CPU wait is required. Smallest passing queued layout: ${queuedPassing[0].name}. Production can retain asynchronous GPU-only execution with multiple queue.submit() calls.`;
        } else if (passing.length) {
            diagnosis = `Apple requires an actual completion wait between GPU stages in this test. Passing layout: ${passing[0].name}. Next benchmark the required waits and test whether a copy/no-op barrier can replace CPU synchronization.`;
        } else {
            diagnosis = 'No submission-boundary layout repaired the pipeline. The remaining difference is runtime/state composition rather than simple queue synchronization; next compare exact M67.29 C1 output immediately after each boundary.';
        }

        const overall = passing.length > 0;
        const lines = [
            overall ? 'PASS - APPLE SUBMISSION-BOUNDARY MATRIX FOUND A CORRECT FULL GPU PATH.' : 'FAIL - SUBMISSION BOUNDARIES ALONE DID NOT REPAIR THE FULL PATH.',
            '',
            'Test version: M67.38-MainContinuousWins-v1',
            `Adapter: ${adapter ? describeAdapter(adapter) : 'unknown'}`,
            '',
            'Reference candidate:',
            `nonce: ${nonce} (0x${nonce.toString(16)})`,
            '',
            'Boundary matrix:',
            ...rows.flatMap(r => [
                `${r.name}:`,
                `  C1 signature=${r.signatureMatch ? 'MATCH' : 'MISMATCH'}`,
                `  C2 stored HASH256=${r.batchHashMatch ? 'MATCH' : 'MISMATCH'}`,
                `  C3 completed=${r.completed}/128`,
                `  diagnostic WG1 replay hash=${r.replayHashMatch ? 'MATCH' : 'MISMATCH'}`,
                `  elapsed=${r.elapsedMs.toFixed(2)} ms`,
            ]),
            '',
            'Interpretation:', diagnosis,
            '',
            'Safety:',
            'Electrum queried: NO',
            'Live PHOTON target mined: NO',
            'Broadcast RPC called: NO',
            'Private key transmitted: NO',
        ];
        setResult(ui.m53HardwareResult, lines.join('\n'), overall ? 'pass' : 'fail');
        setStatus(overall ? 'M67.31 found a correct Apple submission-boundary layout.' : 'M67.31 boundary matrix did not repair the full path.');
        m673RefreshDiagnosticReport();
        return { overall, rows, diagnosis };
    } finally {
        if (ui.runOneGpuCpuSolution) ui.runOneGpuCpuSolution.disabled = false;
    }
}



// ============================================================================
// M67.32 — exact-known-good C1 reproducibility + full single-submit benchmark.
// Do not refactor photon_m6729_c1_znorm_wg64: its expression/lifetime ordering
// is intentionally preserved because Apple/Metal has proven codegen-sensitive.
// ============================================================================
async function m6732CreateExactRuntime({ template, privateKeyHex, candidateCount, baseNonce }) {
    const runtime = await m6724CreateRuntime({
        template,
        privateKeyHex,
        candidateCount,
        baseNonce,
        c1Mode: 'baseline',
    });
    await m6731UseExactPassingC1(runtime);
    return runtime;
}

async function m6732RunSingleSubmit(runtime, baseNonce) {
    return await m6731RunGroups(
        runtime,
        baseNonce,
        [['A','B','C1','C2','C3']],
        false
    );
}

async function m6732ReplayExact({ template, privateKeyHex, nonce }) {
    const runtime = await m6732CreateExactRuntime({
        template,
        privateKeyHex,
        candidateCount: 128,
        baseNonce: nonce,
    });
    try {
        const result = await m6732RunSingleSubmit(runtime, nonce);
        const gpu = await m6724ReadCandidateOutputs(runtime);
        const cpu = await m53CpuCandidate({ template, nonce, privateKeyHex });
        return {
            result,
            gpu,
            cpu,
            signatureMatch: gpu.signatureHex === cpu.signatureHex.toLowerCase(),
            storedBatchHashMatch: gpu.storedBatchHashHex === cpu.hashHex.toLowerCase(),
            replayHashMatch: gpu.hashHex === cpu.hashHex.toLowerCase(),
        };
    } finally {
        runtime.destroy();
    }
}

async function runM6732ExactC1ReproBenchmark() {
    if (!device) throw new Error('Enable WebGPU before running M67.32.');
    if (ui.runOneGpuCpuSolution) ui.runOneGpuCpuSolution.disabled = true;
    if (ui.armLiveBroadcast) ui.armLiveBroadcast.checked = false;

    const benchmarkRows = [];
    let reproRuntime = null;
    let winnerRuntime = null;
    try {
        setStatus('M67.32 repeating exact passing Apple C1, then benchmarking the full single-submit pipeline...');
        setResult(ui.m53HardwareResult, [
            'RUNNING - EXACT APPLE C1 REPRODUCIBILITY + BENCHMARK','',
            'Stage A: optimized RFC6979 with CPU-generated M27 setup state',
            'Stage B: M45 split4 + 16-bit / 64 MiB generator table',
            'Stage C1: EXACT photon_m6729_c1_znorm_wg64 body',
            'Stage C2: M30-prefixed HASH256-only',
            'Stage C3: target comparator / completed / winner atomics',
            'Execution: ONE queue.submit() per mining batch',
            'Live network/broadcast: DISABLED',
        ].join('\n'), '');

        const keyState = getOrCreatePersistentMinerPrivateKey();
        const fixtureTemplate = hexToBytes(PHOTON_VECTOR.photonIntegratedCandidate.unsignedTemplateHex);
        const personalized = await m56TemplateForPrivateKey({
            fixtureTemplate,
            privateKeyHex: keyState.privateKeyHex,
        });
        const template = personalized.template.slice();
        const batonStart = locatePhotonBatonStart(template);
        const targetBytes = new Uint8Array(32);
        targetBytes[31] = 0x04; // synthetic ~difficulty 64
        template.set(targetBytes, batonStart + 4);
        const targetHex = bytesToHexLocal(targetBytes).toLowerCase();

        const precompute = await createM27PrecomputedState(
            keyState.privateKeyHex,
            { transferMode: 'cpu-generated' }
        );
        const tableStarted = performance.now();
        await ensureM29TableBuffer(16);
        await device.queue.onSubmittedWorkDone();
        const tablePrepareMs = performance.now() - tableStarted;
        await createM30TxPrefixState(template);

        // Re-use one real 128-candidate runtime and vary only baseNonce. Candidate
        // zero is independently checked after every full A+B+C1+C2+C3 dispatch.
        reproRuntime = await m6732CreateExactRuntime({
            template,
            privateKeyHex: keyState.privateKeyHex,
            candidateCount: 128,
            baseNonce: 0x4e100123,
        });
        const reproNonces = [
            0x4e100123, 0x4e200123, 0x4e300123, 0x4e400123,
            0x4e500123, 0x4e600123, 0x4e700123, 0x4e800123,
        ];
        const reproRows = [];
        for (const nonce of reproNonces) {
            const result = await m6732RunSingleSubmit(reproRuntime, nonce >>> 0);
            const gpu = await m6724ReadCandidateOutputs(reproRuntime);
            const cpu = await m53CpuCandidate({ template, nonce: nonce >>> 0, privateKeyHex: keyState.privateKeyHex });
            reproRows.push({
                nonce: nonce >>> 0,
                elapsedMs: result.elapsedMs,
                completed: result.completed,
                signatureMatch: gpu.signatureHex === cpu.signatureHex.toLowerCase(),
                storedHashMatch: gpu.storedBatchHashHex === cpu.hashHex.toLowerCase(),
                replayHashMatch: gpu.hashHex === cpu.hashHex.toLowerCase(),
            });
        }
        const reproPass = reproRows.every(r =>
            r.completed === 128 && r.signatureMatch && r.storedHashMatch && r.replayHashMatch
        );
        if (!reproPass) {
            throw new Error('Exact M67.29 C1 did not reproduce strict CPU on all eight single-submit probe nonces.');
        }
        reproRuntime.destroy();
        reproRuntime = null;

        // Find a synthetic GPU winner using the exact-known-good C1.
        winnerRuntime = await m6732CreateExactRuntime({
            template,
            privateKeyHex: keyState.privateKeyHex,
            candidateCount: 1024,
            baseNonce: 0x4f000000,
        });
        let winnerBatch = null;
        for (let batch = 0; batch < 8; batch += 1) {
            const baseNonce = (0x4f000000 + batch * 1024) >>> 0;
            const result = await m6732RunSingleSubmit(winnerRuntime, baseNonce);
            if (result.completed !== 1024) {
                throw new Error(`M67.32 C3 completed ${result.completed}; expected 1024.`);
            }
            if (result.winners > 0 && result.firstWinnerNonce !== null) {
                winnerBatch = { ...result, baseNonce };
                break;
            }
        }
        if (!winnerBatch) {
            throw new Error('Synthetic difficulty-64 search found no GPU winner in 8192 candidates.');
        }
        winnerRuntime.destroy();
        winnerRuntime = null;

        const winnerReplay = await m6732ReplayExact({
            template,
            privateKeyHex: keyState.privateKeyHex,
            nonce: winnerBatch.firstWinnerNonce,
        });
        if (!winnerReplay.signatureMatch || !winnerReplay.storedBatchHashMatch || !winnerReplay.replayHashMatch) {
            throw new Error('GPU winner replay disagrees with strict CPU signature/HASH256.');
        }
        const verified = await cpuVerifyLiveWinner({
            templateBytes: template,
            nonce: winnerBatch.firstWinnerNonce,
            gpuSignatureHex: winnerReplay.gpu.signatureHex,
            gpuHashHex: winnerReplay.gpu.hashHex,
            privateKeyHex: keyState.privateKeyHex,
            expectedPublicKeyHex: personalized.publicKeyHex,
            targetHex,
        });

        setStatus('M67.32 strict correctness PASS; benchmarking exact single-submit Apple pipeline...');
        const ladder = [128, 1024, 4096, 16384, 65536, 131072, 262144, 524288];
        let selected = null;
        for (const candidateCount of ladder) {
            const runtime = await m6732CreateExactRuntime({
                template,
                privateKeyHex: keyState.privateKeyHex,
                candidateCount,
                baseNonce: 0x52000000,
            });
            try {
                await m6732RunSingleSubmit(runtime, 0x52000000);
                const timed = await m6732RunSingleSubmit(runtime, 0x53000000);
                if (timed.completed !== candidateCount) {
                    throw new Error(`Benchmark ${candidateCount}: completed=${timed.completed}.`);
                }
                const hashRate = candidateCount / (timed.elapsedMs / 1000);
                benchmarkRows.push({ candidateCount, elapsedMs: timed.elapsedMs, hashRate });
                if (timed.elapsedMs <= 350) {
                    if (!selected || hashRate > selected.hashRate) {
                        selected = { candidateCount, elapsedMs: timed.elapsedMs, hashRate };
                    }
                }
                if (timed.elapsedMs > 350 && candidateCount >= 16384) break;
            } finally {
                runtime.destroy();
            }
        }
        if (!selected && benchmarkRows.length) {
            selected = benchmarkRows.reduce((a,b) => a.hashRate >= b.hashRate ? a : b);
        }

        const lines = [
            'PASS - EXACT M67.29 APPLE C1 IS REPRODUCIBLE IN THE FULL SINGLE-SUBMIT PIPELINE.','',
            'Test version: M67.38-MainContinuousWins-v1',
            `Adapter: ${adapter ? describeAdapter(adapter) : 'unknown'}`,'',
            'Confirmed architecture:',
            `M27 precompute: ${precompute.transferMode}`,
            'Stage A: optimized RFC6979 consumer',
            'Stage B: M45 B4a/b/c/d + 16-bit / 64 MiB generator table',
            'Stage C1: exact M67.29 normalized-Z baseline WG64 body',
            'Stage C2: separate M30-prefixed HASH256-only WG64',
            'Stage C3: separate winner/completed WG64',
            'Queue submissions per mining batch: 1','',
            'Eight-nonce reproducibility check:',
            ...reproRows.map(r =>
                `0x${r.nonce.toString(16).padStart(8,'0')}: sig=${r.signatureMatch?'MATCH':'MISMATCH'} C2=${r.storedHashMatch?'MATCH':'MISMATCH'} replay=${r.replayHashMatch?'MATCH':'MISMATCH'} completed=${r.completed}/128 ${r.elapsedMs.toFixed(2)} ms`
            ),'',
            'GPU winner -> strict CPU gate:',
            `GPU winner nonce: ${winnerBatch.firstWinnerNonce} (0x${winnerBatch.firstWinnerNonce.toString(16).padStart(8,'0')})`,
            `GPU signature = CPU: ${winnerReplay.signatureMatch ? 'MATCH' : 'MISMATCH'}`,
            `GPU C2 batch HASH256 = CPU: ${winnerReplay.storedBatchHashMatch ? 'MATCH' : 'MISMATCH'}`,
            `GPU replay HASH256 = CPU: ${winnerReplay.replayHashMatch ? 'MATCH' : 'MISMATCH'}`,
            'Strict CPU proof-of-work: PASS',
            `Verified HASH256: ${verified.candidateHashHex}`,'',
            `64 MiB table preparation: ${tablePrepareMs.toFixed(2)} ms`,'',
            'Full single-submit A+B4a+B4b+B4c+B4d+C1+C2+C3 benchmark:',
            ...benchmarkRows.map(r =>
                `${r.candidateCount.toLocaleString().padStart(9)} candidates  ${r.elapsedMs.toFixed(2).padStart(8)} ms  ${r.hashRate.toFixed(2).padStart(11)} H/s`
            ),'',
            selected
                ? `Selected <=350 ms batch: ${selected.candidateCount.toLocaleString()} @ ${selected.hashRate.toFixed(2)} H/s (${selected.elapsedMs.toFixed(2)} ms)`
                : 'Selected batch: none','',
            'Interpretation:',
            'The single-submit path is reproducibly correct when the exact M67.29 C1 expression/lifetime ordering is preserved. M67.30 failed because its mathematically equivalent C1 refactor changed Metal code generation. Keep this exact Apple C1 body intact; optimize it only behind independent correctness tests.','',
            'Safety:',
            'Electrum queried: NO',
            'Live PHOTON target mined: NO',
            'Broadcast RPC called: NO',
            'Private key transmitted: NO',
        ];
        setResult(ui.m53HardwareResult, lines.join('\n'), 'pass');
        setStatus('M67.32 exact C1 reproducibility + full benchmark PASS.');
        m673RefreshDiagnosticReport();
        return { reproRows, winnerBatch, benchmarkRows, selected };
    } finally {
        reproRuntime?.destroy?.();
        winnerRuntime?.destroy?.();
        if (ui.runOneGpuCpuSolution) ui.runOneGpuCpuSolution.disabled = false;
    }
}

