if (
    ui.runM50Live
) {
    ui.runM50Live.addEventListener(
        "click",
        async () => {
            try {
                await runM50LiveMining();

            } catch (error) {
                console.error(
                    error
                );

                let persistedStage =
                    null;

                try {
                    const prior =
                        JSON.parse(
                            localStorage.getItem(
                                M57_PROGRESS_KEY
                            ) ??
                            "null"
                        );

                    persistedStage =
                        prior?.stage ??
                        null;

                } catch {
                }

                const currentStageUsable =
                    m57CurrentStage &&
                    m57CurrentStage !==
                        "not started";

                const failedStage =
                    error?.m57Stage ??
                    (
                        currentStageUsable
                            ? m57CurrentStage
                            : persistedStage
                    ) ??
                    "unknown M67.1 stage";

                m57ProgressRecord({
                    status:
                        "failed",
                    stage:
                        failedStage,
                    detail:
                        String(
                            error?.message ??
                            error
                        ),
                });

                setResult(
                    ui.m50LiveResult,
                    [
                        `M67.1 failure stage: ${failedStage}`,
                        "",
                        String(
                            error?.stack ??
                            error
                        ),
                    ].join(
                        "\n"
                    ),
                    "fail"
                );

                setStatus(
                    `M67.1 adaptive real mainnet mining failed at: ${failedStage}`
                );

                m50SetRunning(
                    false
                );
            }
        }
    );
}


